#include "volumetric_kit/grid/base/dispatch.hpp"

#include <atomic>
#include <limits>
#include <string>

#include "volumetric_kit/core/vulkan/compute_util.hpp"

// Embedded SPIR-V (generated by vgrid_embed_shaders onto a PRIVATE include
// path).
#include "dispatch_args_comp.spv.hpp"

namespace volumetric_kit::grid::detail {
namespace {

std::atomic<std::uint32_t> g_test_groups{0};

// Mirrors `Push` in base/shaders/dispatch_args.comp.
struct ArgsPush {
  std::uint32_t count_word;
  std::uint32_t gate_word;
  std::uint32_t bound;
  std::uint32_t multiplier;
  std::uint32_t per_dispatch;
  std::uint32_t lanes0;
  std::uint32_t dispatches0;
  std::uint32_t lanes1;
  std::uint32_t dispatches1;
};
static_assert(sizeof(ArgsPush) == 36, "ArgsPush must be 36 bytes");

// dispatch_args.comp's word index that names no word.
constexpr std::uint32_t kNoWord = ~0u;

}  // namespace

std::uint32_t groups_per_dispatch(std::uint32_t max_groups) {
  const std::uint32_t cap = g_test_groups.load(std::memory_order_relaxed);
  return cap == 0 ? max_groups : std::min(cap, max_groups);
}

void set_test_groups_per_dispatch(std::uint32_t groups) {
  g_test_groups.store(groups, std::memory_order_relaxed);
}

std::uint32_t slice_count(std::uint64_t max_items, std::uint32_t lanes,
                          std::uint32_t per_dispatch) {
  const std::uint64_t groups = (max_items + lanes - 1) / lanes;
  const std::uint64_t slices = (groups + per_dispatch - 1) / per_dispatch;
  return static_cast<std::uint32_t>(std::max<std::uint64_t>(slices, 1));
}

core::Status add_dispatch_args(core::KernelSetBuilder& kb,
                               core::ComputeKernel& kernel, const char* name) {
  VkPushConstantRange push{};
  push.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
  push.size = sizeof(ArgsPush);
  return kb.add(kernel, name, vgrid_dispatch_args_comp_spv,
                vgrid_dispatch_args_comp_spv_size, 3, &push);
}

core::Status record_dispatch_args(
    core::CommandBatch& batch, core::Device& device, core::Allocator& allocator,
    core::ComputeKernel& kernel, core::Buffer& buffer, const char* name,
    const SlicedCount& count, std::uint32_t lanes, IndirectSlices* slices,
    std::uint32_t second_lanes, IndirectSlices* second,
    std::uint32_t max_groups, core::GpuStageScope* stage) {
  const auto refuse = [&](const char* why) {
    return core::Status::invalid_argument(
        std::string("record_dispatch_args: ") + name + ": " + why);
  };
  if (count.offset % 4 != 0 || count.gate_offset % 4 != 0) {
    return refuse("a misaligned word");
  }
  const std::uint64_t max_items =
      std::uint64_t(count.bound) * std::uint64_t(count.multiplier);
  if (max_items > std::numeric_limits<std::uint32_t>::max()) {
    return refuse("past 2^32 items");
  }
  const std::uint32_t per_dispatch = groups_per_dispatch(max_groups);
  const std::uint32_t first = slice_count(max_items, lanes, per_dispatch);
  const std::uint32_t then =
      second_lanes != 0 ? slice_count(max_items, second_lanes, per_dispatch)
                        : 0;
  const VkDeviceSize bytes =
      VkDeviceSize(first + then) * sizeof(VkDispatchIndirectCommand);
  if (buffer.size() < bytes) {
    VKC_ASSIGN(buffer,
               core::device_storage_buffer(
                   allocator, bytes, VK_BUFFER_USAGE_INDIRECT_BUFFER_BIT));
    device.set_object_name(VK_OBJECT_TYPE_BUFFER,
                           core::debug_object_handle(buffer.handle()), name);
  }
  // The count's buffer stands in for an absent gate's, and the gate's for a
  // count the host knows: the kernel reads neither.
  const core::Buffer& counts = count.buffer != nullptr ? *count.buffer
                               : count.gate != nullptr ? *count.gate
                                                       : buffer;
  const core::Buffer& gates = count.gate != nullptr ? *count.gate : counts;
  kernel.set.write_storage_buffer(0, counts.handle(), 0, VK_WHOLE_SIZE);
  kernel.set.write_storage_buffer(1, gates.handle(), 0, VK_WHOLE_SIZE);
  kernel.set.write_storage_buffer(2, buffer.handle(), 0, bytes);
  const ArgsPush push{
      count.buffer != nullptr ? std::uint32_t(count.offset / 4) : kNoWord,
      count.gate != nullptr ? std::uint32_t(count.gate_offset / 4) : kNoWord,
      count.bound,
      count.multiplier,
      per_dispatch,
      lanes,
      first,
      second_lanes,
      then};
  VKC_TRY(batch.dispatch(kernel, &push, sizeof(push), 1, max_groups, stage));
  *slices = IndirectSlices{&buffer, 0, first, per_dispatch, lanes};
  if (second != nullptr) {
    *second = IndirectSlices{
        &buffer, VkDeviceSize(first) * sizeof(VkDispatchIndirectCommand), then,
        per_dispatch, second_lanes};
  }
  return {};
}

}  // namespace volumetric_kit::grid::detail
